import React, { useEffect, useState } from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { 
  ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, BarChart, Bar 
} from "recharts";
import { 
  Utensils, TrendingUp, Leaf, DollarSign, Users, LogOut, Settings, 
  PieChart, Truck, PlusCircle, CheckCircle2, ShieldAlert, RefreshCw, ArrowRight,
  CloudSun, Calendar, AlertTriangle, CheckCircle, BarChart3
} from "lucide-react";

// ==========================================
// 1. AUTHENTICATION PAGE
// ==========================================
function AuthPage({ onLogin }) {
  const [mode, setMode] = useState("signin");
  const [email, setEmail] = useState("admin@canteen.org");
  const [password, setPassword] = useState("password123");
  const [role, setRole] = useState("Admin/Canteen Manager");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    const endpoint = mode === "signin" ? "/api/auth/login" : "/api/auth/register";

    fetch(`http://localhost:8000${endpoint}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password, role }),
    })
      .then(async (res) => {
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || "Authentication failed");
        return data;
      })
      .then((data) => {
        setLoading(false);
        onLogin(data.user);
      })
      .catch((err) => {
        setLoading(false);
        setError(err.message);
      });
  };

  return (
    <div className="min-h-screen w-full grid grid-cols-1 lg:grid-cols-2 font-sans bg-[#F4F5F0]">
      {/* Hero Banner */}
      <div className="relative min-h-[350px] lg:min-h-screen bg-slate-900 flex flex-col justify-between p-8 sm:p-14 overflow-hidden">
        <div 
          className="absolute inset-0 bg-cover bg-center opacity-60 z-0"
          style={{ backgroundImage: `url('https://images.unsplash.com/photo-1593113598332-cd288d649433?q=80&w=1200')` }}
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#0f2317] via-[#122e1e]/80 to-[#122e1e]/60 z-10" />

        <div className="relative z-20">
          <span className="text-emerald-400 font-bold tracking-widest text-xs uppercase">
            PLATEAI / FOODWISE · FOOD WITH PURPOSE
          </span>
        </div>

        <div className="relative z-20 my-auto max-w-lg pt-12 lg:pt-0">
          <h1 className="text-4xl sm:text-6xl font-light text-white tracking-tight leading-[1.1] mb-6">
            Serve what <br />
            <span className="font-normal italic font-serif">matters.</span>
          </h1>
          <p className="text-stone-300 text-base sm:text-lg leading-relaxed font-light">
            AI-powered demand forecasting, safety verification, and surplus food redistribution.
          </p>
        </div>

        <div className="relative z-20 text-xs text-stone-400 hidden lg:block">
          © {new Date().getFullYear()} PlateAI Control Systems. All rights reserved.
        </div>
      </div>

      {/* Form Panel */}
      <div className="flex flex-col justify-center p-6 sm:p-12 lg:p-20 text-slate-800">
        <div className="max-w-md w-full mx-auto space-y-8">
          <div>
            <span className="text-[11px] font-bold tracking-widest text-emerald-800 uppercase block mb-2">
              WORKSPACE ACCESS
            </span>
            <h2 className="text-3xl font-semibold text-slate-900 mb-1">Good to see you.</h2>
            <p className="text-slate-600 text-sm">Run the full canteen-to-community flow from one place.</p>
          </div>

          <div className="bg-[#E4E6DF] p-1 rounded-2xl flex items-center gap-1">
            <button
              type="button"
              onClick={() => setMode("signin")}
              className={`flex-1 py-3 text-sm font-semibold rounded-xl transition-all ${
                mode === "signin" ? "bg-white text-slate-900 shadow-sm" : "text-slate-600"
              }`}
            >
              Sign in
            </button>
            <button
              type="button"
              onClick={() => setMode("register")}
              className={`flex-1 py-3 text-sm font-semibold rounded-xl transition-all ${
                mode === "register" ? "bg-white text-slate-900 shadow-sm" : "text-slate-600"
              }`}
            >
              Register
            </button>
          </div>

          {error && <div className="bg-red-50 text-red-700 text-xs px-4 py-3 rounded-xl border border-red-200">{error}</div>}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="text-xs font-semibold text-slate-700 block mb-1">Email</label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-[#EAECE5]/70 border focus:border-emerald-600 focus:bg-white text-slate-900 text-sm px-4 py-3 rounded-xl outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-semibold text-slate-700 block mb-1">Password</label>
              <input
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-[#EAECE5]/70 border focus:border-emerald-600 focus:bg-white text-slate-900 text-sm px-4 py-3 rounded-xl outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-semibold text-slate-700 block mb-1">Role</label>
              <select
                value={role}
                onChange={(e) => setRole(e.target.value)}
                className="w-full bg-[#EAECE5]/70 border focus:border-emerald-600 focus:bg-white text-slate-900 text-sm px-4 py-3 rounded-xl outline-none"
              >
                <option value="Admin/Canteen Manager">Admin / Canteen Manager</option>
                <option value="Recipient/NGO">Recipient / NGO</option>
                <option value="System/AI">System / AI Operator</option>
              </select>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-[#125A38] hover:bg-[#0e482d] text-white font-medium text-sm py-3.5 rounded-xl flex items-center justify-center gap-2 transition"
            >
              <span>{loading ? "Signing in..." : mode === "signin" ? "Sign in" : "Register"}</span>
              <ArrowRight size={16} />
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

// ==========================================
// 2. MAIN DASHBOARD & NAVIGATION
// ==========================================
function MainApp({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState("Dashboard");
  const [attendanceList, setAttendanceList] = useState([]);
  const [surplusList, setSurplusList] = useState([]);
  const [recipientsList, setRecipientsList] = useState([]);
  const [analyticsData, setAnalyticsData] = useState(null);

  // AI Prediction State
  const [attInput, setAttInput] = useState(850);
  const [eventInput, setEventInput] = useState(false);
  const [holidayInput, setHolidayInput] = useState(false);
  const [tempInput, setTempInput] = useState(28.0);
  const [rainInput, setRainInput] = useState(false);
  const [forecastResult, setForecastResult] = useState(null);

  // Surplus Input State
  const [dishName, setDishName] = useState("");
  const [prepQty, setPrepQty] = useState(400);
  const [consumedQty, setConsumedQty] = useState(360);
  const [prepTime, setPrepTime] = useState("12:30 PM");
  const [storageTemp, setStorageTemp] = useState(62.0);

  const fetchAllData = () => {
    fetch("http://localhost:8000/api/attendance").then(r => r.json()).then(setAttendanceList);
    fetch("http://localhost:8000/api/surplus").then(r => r.json()).then(setSurplusList);
    fetch("http://localhost:8000/api/recipients").then(r => r.json()).then(setRecipientsList);
    fetch("http://localhost:8000/api/analytics").then(r => r.json()).then(setAnalyticsData);
  };

  useEffect(() => {
    fetchAllData();
  }, []);

  const runAIPrediction = (e) => {
    e?.preventDefault();
    fetch("http://localhost:8000/api/forecast", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        attendance: Number(attInput),
        day: "Monday",
        event: eventInput,
        holiday: holidayInput,
        temperature_c: Number(tempInput),
        rain: rainInput,
        meal_type: "Lunch"
      })
    })
      .then(r => r.json())
      .then(setForecastResult);
  };

  const submitSurplus = (e) => {
    e.preventDefault();
    fetch("http://localhost:8000/api/surplus", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        dish: dishName,
        prepared_qty: Number(prepQty),
        consumed_qty: Number(consumedQty),
        prep_time: prepTime,
        storage_temp_c: Number(storageTemp)
      })
    })
      .then(r => r.json())
      .then(() => {
        setDishName("");
        fetchAllData();
      });
  };

  const dispatchMatch = (surplusId, recipientId) => {
    fetch("http://localhost:8000/api/redistribution/match", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ surplus_id: surplusId, recipient_id: recipientId })
    })
      .then(r => r.json())
      .then(() => fetchAllData());
  };

  const navItems = [
    { label: "Dashboard", icon: PieChart, roles: ["Admin/Canteen Manager", "Recipient/NGO", "System/AI"] },
    { label: "Demand Forecast", icon: TrendingUp, roles: ["Admin/Canteen Manager", "System/AI"] },
    { label: "Meal Management", icon: Utensils, roles: ["Admin/Canteen Manager"] },
    { label: "Surplus & Safety", icon: ShieldAlert, roles: ["Admin/Canteen Manager", "System/AI"] },
    { label: "Recipients & Matching", icon: Truck, roles: ["Admin/Canteen Manager", "Recipient/NGO"] },
    { label: "Impact Analytics", icon: Leaf, roles: ["Admin/Canteen Manager", "Recipient/NGO", "System/AI"] },
    { label: "Settings", icon: Settings, roles: ["Admin/Canteen Manager", "Recipient/NGO", "System/AI"] },
  ];

  return (
    <div className="flex h-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col justify-between">
        <div>
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-emerald-500 p-2 rounded-xl text-slate-950 font-bold">
              <Utensils size={22} />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white">Plate<span className="text-emerald-400">AI</span></h1>
              <p className="text-[10px] text-slate-400">FoodWise Engine</p>
            </div>
          </div>

          <nav className="p-4 space-y-1">
            {navItems.filter(item => item.roles.includes(user.role)).map((item) => {
              const Icon = item.icon;
              const isActive = activeTab === item.label;
              return (
                <button
                  key={item.label}
                  onClick={() => setActiveTab(item.label)}
                  className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                    isActive
                      ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 shadow-sm"
                      : "text-slate-400 hover:bg-slate-800 hover:text-slate-200"
                  }`}
                >
                  <Icon size={18} />
                  {item.label}
                </button>
              );
            })}
          </nav>
        </div>

        {/* User Info */}
        <div className="p-4 border-t border-slate-800">
          <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-xl border border-slate-800">
            <div className="overflow-hidden">
              <p className="text-xs font-semibold text-white truncate">{user.name}</p>
              <p className="text-[10px] text-emerald-400 truncate">{user.role}</p>
            </div>
            <button onClick={onLogout} title="Sign Out" className="text-slate-400 hover:text-red-400 p-1">
              <LogOut size={16} />
            </button>
          </div>
        </div>
      </aside>

      {/* Main Panel */}
      <main className="flex-1 flex flex-col overflow-y-auto bg-slate-950">
        <header className="px-8 py-5 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between backdrop-blur-md sticky top-0 z-10">
          <div>
            <h2 className="text-xl font-bold text-white">{activeTab}</h2>
            <p className="text-xs text-slate-400">System Mode: {user.role}</p>
          </div>
          <button onClick={fetchAllData} className="p-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700">
            <RefreshCw size={18} />
          </button>
        </header>

        <div className="p-8 max-w-7xl w-full mx-auto space-y-8">

          {/* TAB 1: DASHBOARD */}
          {activeTab === "Dashboard" && (
            <div className="space-y-8">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
                <MetricCard title="Today's Expected Demand" value="425 meals" subtitle="AI Prediction" icon={Users} color="emerald" />
                <MetricCard title="Recommended Prep" value="440 meals" subtitle="+15 buffer" icon={Utensils} color="blue" />
                <MetricCard title="Actual Consumption" value="410 meals" subtitle="Live Turnout" icon={TrendingUp} color="indigo" />
                <MetricCard title="Safe Surplus" value="30 meals" subtitle="Redistributable" icon={ShieldAlert} color="amber" />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
                <ImpactCard title="Food Saved" value="12.5 kg" badge="This Week" />
                <ImpactCard title="Cost Saved" value="₹1,850" badge="Estimated" />
                <ImpactCard title="CO₂ Avoided" value="28 kg" badge="Green Impact" />
              </div>

              <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800">
                <h3 className="text-base font-semibold text-white mb-4">Predicted vs Actual Consumption</h3>
                <div className="h-72 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={[
                      { day: "Mon", predicted: 420, actual: 410 },
                      { day: "Tue", predicted: 430, actual: 425 },
                      { day: "Wed", predicted: 440, actual: 435 },
                      { day: "Thu", predicted: 450, actual: 445 },
                      { day: "Fri", predicted: 460, actual: 455 },
                    ]}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                      <XAxis dataKey="day" stroke="#94a3b8" />
                      <YAxis stroke="#94a3b8" />
                      <Tooltip contentStyle={{ backgroundColor: "#0f172a", borderColor: "#334155" }} />
                      <Legend />
                      <Line type="monotone" dataKey="predicted" stroke="#10b981" strokeWidth={3} />
                      <Line type="monotone" dataKey="actual" stroke="#6366f1" strokeWidth={3} />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          )}

          {/* TAB 2: DEMAND FORECAST (STEP 7, 8, 9) */}
          {activeTab === "Demand Forecast" && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <form onSubmit={runAIPrediction} className="bg-slate-900 p-6 rounded-2xl border border-slate-800 space-y-4">
                <h3 className="text-lg font-bold text-white flex items-center gap-2">
                  <TrendingUp size={20} className="text-emerald-400" /> AI Forecasting Parameters
                </h3>

                <div>
                  <label className="text-xs text-slate-300 block mb-1">Expected Attendance Input</label>
                  <input type="number" value={attInput} onChange={e => setAttInput(e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm text-white" />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <label className="flex items-center gap-2 text-xs text-slate-300 cursor-pointer bg-slate-800 p-3 rounded-xl border border-slate-700">
                    <input type="checkbox" checked={eventInput} onChange={e => setEventInput(e.target.checked)} />
