                  </label>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs text-slate-300 block mb-1">Temperature (°C)</label>
                    <input type="number" value={tempInput} onChange={e => setTempInput(e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm text-white" />
                  </div>
                  <label className="flex items-center gap-2 text-xs text-slate-300 cursor-pointer bg-slate-800 p-3 rounded-xl border border-slate-700 mt-5">
                    <input type="checkbox" checked={rainInput} onChange={e => setRainInput(e.target.checked)} />
