                  </label>
                </div>

                <button type="submit" className="w-full bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-semibold py-3 rounded-xl transition">
                  Run ML Demand Prediction
                </button>
              </form>

              {/* Recommendation Output */}
              <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 flex flex-col justify-between">
                <div>
                  <h3 className="text-lg font-bold text-white mb-4">Actionable Recommendation</h3>
                  {forecastResult ? (
