                          <p className="text-xl font-bold text-blue-400">+{forecastResult.safety_buffer}</p>
                        </div>
                        <div className="bg-slate-800 p-3 rounded-xl">
                          <p className="text-[10px] text-slate-400">Recommend Prep</p>
                          <p className="text-xl font-bold text-amber-400">{forecastResult.recommended_prep}</p>
                        </div>
                      </div>

                      <div className="bg-slate-800/60 p-4 rounded-xl border border-slate-800">
                        <p className="text-xs font-semibold text-slate-200 mb-2">Explainable AI Reasoning:</p>
                        <ul className="space-y-1.5 text-xs text-slate-400 list-disc pl-4">
                          {forecastResult.explainability.map((reason, idx) => (
                            <li key={idx}>{reason}</li>
