                        <td className="p-3">{row.day}</td>
                        <td className="p-3 font-bold text-emerald-400">{row.attendance}</td>
                        <td className="p-3">{row.meal_type}</td>
                        <td className="p-3">{row.event ? "Yes" : "No"}</td>
                        <td className="p-3">{row.holiday ? "Yes" : "No"}</td>
