                <div>
                  <label className="text-xs text-slate-300 block mb-1">Dish Name</label>
                  <input type="text" required value={dishName} onChange={e => setDishName(e.target.value)} placeholder="e.g. Mixed Vegetable Curry" className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm text-white" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs text-slate-300 block mb-1">Prepared Quantity</label>
                    <input type="number" value={prepQty} onChange={e => setPrepQty(e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm text-white" />
                  </div>
                  <div>
                    <label className="text-xs text-slate-300 block mb-1">Consumed Quantity</label>
                    <input type="number" value={consumedQty} onChange={e => setConsumedQty(e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm text-white" />
                  </div>
                </div>
                <div>
                  <label className="text-xs text-slate-300 block mb-1">Storage Temperature (°C)</label>
                  <input type="number" step="0.1" value={storageTemp} onChange={e => setStorageTemp(e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm text-white" />
