              </form>

              <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800">
                <h3 className="text-lg font-bold text-white mb-4">Surplus Verification Logs</h3>
                <div className="space-y-3">
                  {surplusList.map((item) => (
                    <div key={item.id} className="bg-slate-800/50 p-4 rounded-xl border border-slate-800 flex justify-between items-center">
                      <div>
                        <p className="text-sm font-bold text-white">{item.dish}</p>
                        <p className="text-xs text-slate-400">Surplus: {item.surplus_qty} meals | Temp: {item.storage_temp_c}°C</p>
