          {/* TAB 5: RECIPIENT MATCHING (STEP 12) */}
          {activeTab === "Recipients & Matching" && (
            <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 space-y-6">
              <h3 className="text-lg font-bold text-white">Eligible Recipient NGOs & Dispatch Matching</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                {recipientsList.map((rec) => (
                  <div key={rec.id} className="bg-slate-800/60 p-5 rounded-2xl border border-slate-700 flex flex-col justify-between">
                    <div>
                      <div className="flex justify-between items-center mb-2">
                        <h4 className="font-bold text-white text-sm">{rec.name}</h4>
                        <span className="text-[10px] bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-2 py-0.5 rounded-full">Verified</span>
                      </div>
                      <p className="text-xs text-slate-400">Distance: {rec.distance_km} km</p>
                      <p className="text-xs text-slate-400">Meal Capacity: {rec.capacity} meals</p>
                    </div>
                    <button 
                      onClick={() => dispatchMatch(1, rec.id)}
                      className="mt-4 w-full bg-slate-700 hover:bg-emerald-500 hover:text-slate-950 text-slate-200 text-xs font-bold py-2.5 rounded-xl transition"
                    >
                      Match & Dispatch Available Surplus
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* TAB 6: IMPACT ANALYTICS (STEP 14) */}
          {activeTab === "Impact Analytics" && analyticsData && (
            <div className="space-y-8">
              <div className="grid grid-cols-2 lg:grid-cols-5 gap-4 text-center">
                <ImpactMetric title="Food Saved" value={`${analyticsData.impact.food_saved_kg} kg`} />
                <ImpactMetric title="Meals Saved" value={analyticsData.impact.meals_saved} />
                <ImpactMetric title="Money Saved" value={analyticsData.impact.money_saved_inr} />
                <ImpactMetric title="CO₂ Avoided" value={`${analyticsData.impact.co2_avoided_kg} kg`} />
                <ImpactMetric title="Waste Reduced" value={analyticsData.impact.waste_reduction_pct} />
              </div>

              <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800">
                <h3 className="text-base font-semibold text-white mb-2">Surplus Rate: Before AI vs After AI</h3>
                <p className="text-xs text-slate-400 mb-6">Demonstrating reduction from 15% average surplus down to ~6%</p>
                <div className="h-72 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={analyticsData.before_vs_after}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                      <XAxis dataKey="month" stroke="#94a3b8" />
                      <YAxis stroke="#94a3b8" />
                      <Tooltip contentStyle={{ backgroundColor: "#0f172a", borderColor: "#334155" }} />
                      <Legend />
                      <Bar dataKey="before_ai_surplus" name="Before AI (%)" fill="#ef4444" />
                      <Bar dataKey="after_ai_surplus" name="After AI (%)" fill="#10b981" />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          )}

          {/* TAB 7: SETTINGS */}
          {activeTab === "Settings" && (
            <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800">
              <h3 className="text-lg font-bold text-white mb-4">System Settings</h3>
              <p className="text-xs text-slate-400">Configure safety thresholds, API connections, and notification preferences.</p>
            </div>
          )}

        </div>
      </main>
    </div>
  );
}

// Helpers
function MetricCard({ title, value, subtitle, icon: Icon, color }) {
  return (
    <div className="bg-slate-900 p-5 rounded-2xl border border-slate-800">
      <div className="flex justify-between items-center mb-2">
        <span className="text-xs text-slate-400">{title}</span>
        <Icon size={18} className="text-emerald-400" />
      </div>
      <p className="text-2xl font-bold text-white">{value}</p>
      <p className="text-[11px] text-slate-400">{subtitle}</p>
    </div>
  );
}

function ImpactCard({ title, value, badge }) {
  return (
    <div className="bg-slate-900 p-5 rounded-2xl border border-slate-800 flex justify-between items-center">
      <div>
        <span className="text-xs text-slate-400">{title}</span>
        <p className="text-2xl font-extrabold text-emerald-400">{value}</p>
      </div>
      <span className="text-[10px] bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-2 py-1 rounded-full">{badge}</span>
    </div>
  );
}

function ImpactMetric({ title, value }) {
  return (
    <div className="bg-slate-900 p-4 rounded-xl border border-slate-800">
      <p className="text-[11px] text-slate-400">{title}</p>
      <p className="text-xl font-bold text-emerald-400">{value}</p>
    </div>
  );
}

// Root Application Entry
export default function App() {
  const [user, setUser] = useState(() => {
    const saved = localStorage.getItem("plateai_user");
    return saved ? JSON.parse(saved) : null;
  });

  const handleLogin = (u) => {
    setUser(u);
    localStorage.setItem("plateai_user", JSON.stringify(u));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem("plateai_user");
  };

  return (
    <BrowserRouter>
      <Routes>
        <Route path="/login" element={user ? <Navigate to="/" replace /> : <AuthPage onLogin={handleLogin} />} />
        <Route path="/*" element={user ? <MainApp user={user} onLogout={handleLogout} /> : <Navigate to="/login" replace />} />
      </Routes>
    </BrowserRouter>
  );
}
